#!/usr/bin/env perl
# Generated by the Superpowers bootstrap — blocks agent tools from reading secret
# files (.env, private keys, credentials). Re-running the bootstrap overwrites
# this file; add your own patterns to .secretsignore in the project root instead
# (one glob per line, "!glob" to allow, # for comments).
#
# Usage: perl secret-guard.pl claude|codex|copilot|cursor|antigravity < hook-input.json
use strict;
use warnings;
use Cwd qw(abs_path);
use File::Glob qw(bsd_glob);
use JSON::PP;

my $format = $ARGV[0] // 'copilot';
my $raw = do { local $/; <STDIN> } // '';
my $in = eval { JSON::PP->new->decode($raw) };
exit 0 unless ref $in eq 'HASH';

# Each harness names the tool call differently.
my $args;
if (ref $in->{toolCall} eq 'HASH') { $args = $in->{toolCall}{args} }        # Antigravity
elsif (exists $in->{tool_input})   { $args = $in->{tool_input} }            # Claude Code, Codex
elsif (exists $in->{toolArgs})     { $args = $in->{toolArgs} }              # Copilot
else { $args = { map { exists $in->{$_} ? ($_ => $in->{$_}) : () } qw(file_path command) } }  # Cursor
$args = (eval { JSON::PP->new->decode($args) } // { command => $args }) if defined $args && !ref $args;
exit 0 unless ref $args eq 'HASH';

# The project root: two levels above this script (<root>/.<agent>/hooks/).
my $root = $ENV{CLAUDE_PROJECT_DIR} // do {
  my $self = abs_path($0) // $0;
  $self =~ s{/[^/]+/hooks/[^/]+$}{};
  $self;
};
my $cwd = $args->{Cwd} // $in->{cwd} // $root;

# Which argument values are paths and which are shell commands. Search
# patterns and file contents are not checked, so writing code that mentions
# ".env" or searching source files for it still works.
my (@paths, @commands);
for my $key (keys %$args) {
  my @values = grep { defined && !ref } (ref $args->{$key} eq 'ARRAY' ? @{ $args->{$key} } : $args->{$key});
  if ($key =~ /^(command|cmd|script|commandline)$/i) { push @commands, @values }
  elsif ($key =~ /^cwd$/i) { next }
  elsif ($key eq 'pattern' && ($in->{tool_name} // $in->{toolName} // '') =~ /^glob$/i) { push @paths, @values }
  elsif ($key =~ /path|file|uri|dir|glob/i && $key !~ /content|text/i) { push @paths, @values }
}

my (@deny, @allow);
if (open my $fh, '<', "$root/.secretsignore") {
  while (my $line = <$fh>) {
    $line =~ s/^\s+|\s+$//g;
    next if $line eq '' || $line =~ /^#/;
    if ($line =~ s/^!//) { push @allow, glob_re($line) } else { push @deny, glob_re($line) }
  }
}

sub glob_re {
  my $re = quotemeta shift;
  $re =~ s/\\\*\\\*/.*/g;
  $re =~ s/\\\*/[^\/]*/g;
  $re =~ s/\\\?/[^\/]/g;
  return qr/(?:^|\/)$re$/;
}

sub normalize {
  my $path = shift;
  $path =~ s{^file://}{};
  $path =~ s{\\}{/}g;
  $path =~ s{/+$}{};
  return $path;
}

sub is_secret {
  my $path = normalize(shift);
  (my $base = $path) =~ s{.*/}{};
  return 0 if grep { $path =~ $_ } @allow;
  return 1 if grep { $path =~ $_ } @deny;
  return 0 if $base =~ /^\.env\.(example|sample|template|dist|defaults?)$/i;
  return 0 if $base =~ /\.pub$/;
  return 1 if $base =~ /^\.env([.*].*)?$/i || $base eq '.envrc';
  return 1 if $base =~ /\.(pem|key|p12|pfx|jks|keystore|ppk|tfvars|tfstate)$/i;
  return 1 if $base =~ /^id_(rsa|dsa|ecdsa|ed25519)$/;
  return 1 if $base =~ /^(\.npmrc|\.pypirc|\.netrc|\.git-credentials|\.htpasswd)$/;
  return 1 if $base =~ /^(credentials|secrets?)(\.(json|ya?ml|toml|ini|txt))?$/i;
  return 1 if $base =~ /service[-_]?account.*\.json$/i;
  return 1 if $path =~ m{(^|/)\.(ssh|gnupg|aws)(/|$)};
  return 0;
}

# A word of a shell command counts only if it names a secret file that exists
# (globs expanded), so `grep '\.env' src/` or `echo .env` are not blocked.
sub command_word_is_secret {
  my $word = normalize(shift);
  return 0 unless length $word;
  $word =~ s{^~(?=/|$)}{$ENV{HOME} // '~'}e;
  my $abs = $word =~ m{^(/|[A-Za-z]:/)} ? $word : "$cwd/$word";
  return scalar grep { is_secret($_) } bsd_glob($abs) if $word =~ /[*?\[]/;
  return is_secret($word) && -e $abs;
}

my ($hit) = grep { is_secret($_) } @paths;
($hit) = grep { command_word_is_secret($_) } map { split /[\s;|&<>()`'"=,]+/ } @commands unless defined $hit;
exit 0 unless defined $hit;

my $reason = "Blocked by the project's secret-file guard: '$hit' looks like a secret file "
  . "(.env, private key, credentials). Do not read or copy it. If you need a value from it, "
  . "ask the user, or use a template such as .env.example. Exceptions go in .secretsignore (!pattern).";
my $json = JSON::PP->new->canonical;
if ($format eq 'antigravity') {          # decision JSON on stdout; exit codes undocumented
  print $json->encode({ decision => 'deny', reason => $reason }), "\n";
  exit 0;
}
if ($format eq 'cursor') {
  print $json->encode({ permission => 'deny', user_message => $reason, agent_message => $reason }), "\n";
} elsif ($format eq 'copilot') {
  print $json->encode({ permissionDecision => 'deny', permissionDecisionReason => $reason }), "\n";
}
print STDERR "$reason\n";                # claude, codex: exit 2 + reason on stderr
exit 2;
